std::array<double,20> Values(const Jet&u){std::array<double,20>v{};v[0]=u.alpha.value.d;v[1]=u.chi.value.d;v[2]=u.trace.value.d;v[3]=u.theta.value.d;const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};for(int i=0;i<3;++i){v[4+i]=u.beta.value[i].d;v[17+i]=u.lambda.value[i].d;}for(int k=0;k<5;++k){v[7+k]=u.metric.g[ti[k]][tj[k]].d;v[12+k]=u.a.k[ti[k]][tj[k]].d;}return v;}
std::array<double,20> RHS(const hyp::LayerPoint<double>&p,const Jet&u){auto f=Parts(p,u,10,3,true);std::array<double,20>v{};for(int k=0;k<20;++k)v[k]=f.r[k].d+f.s[k].d/p.omega;return v;}
void Bar(const std::array<double,20>&F,double h[3][3]){const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};for(int k=0;k<5;++k)h[ti[k]][tj[k]]=h[tj[k]][ti[k]]=F[7+k];h[2][2]=-h[0][0]-h[1][1];for(int i=0;i<3;++i)h[i][i]-=F[1];}
double NullFirst(const hyp::LayerPoint<double>&p,const Jet&u,const std::array<double,3>&n,double a){auto gg=hyp::Geometry(u.metric);auto om=Omega(u,p);double ret=0;for(int z=0;z<3;++z){D dG{};for(int i=0;i<3;++i)for(int j=0;j<3;++j){D di{};for(int v=0;v<3;++v)for(int w=0;w<3;++w)di-=gg.inverse[i][v]*u.metric.dg[z][v][w]*gg.inverse[w][j];dG+=(u.chi.d[z]*gg.inverse[i][j]+u.chi.value*di)*D(p.domega[i]*p.domega[j])+u.chi.value*gg.inverse[i][j]*D(p.omega_hessian[z][i]*p.domega[j]+p.domega[i]*p.omega_hessian[z][j]);}ret-=a*n[z]*(dG-D(2)*om.normal*om.dnormal[z]).d;}return ret;}
