 for(int lev=0;lev<3;++lev)for(int k=0;k<4;++k){double O=std::ldexp(.001,-lev)*(k+1),r=std::sqrt(1-2*a*O);auto p=ref.At(r*n[0],r*n[1],r*n[2]);auto u=Field(p,a,which,false),f=Field(p,a,which,true);auto F=RHS(p,u),G=RHS(p,f),oracle=Values(f);for(int z=0;z<20;++z)match=std::max(match,std::abs(F[z]-oracle[z]));double h1[3][3]{},h2[3][3]{};Bar(F,h1);Bar(G,h2);double Y[3]{};for(int i=0;i<3;++i){Y[i]=F[4+i];for(int j=0;j<3;++j)Y[i]-=r*h1[i][j]*n[j]/a;}double yn=0;for(int i=0;i<3;++i)yn+=n[i]*Y[i];for(int i=0;i<3;++i)yt[lev][i]+=w[k]*(Y[i]-yn*n[i]);for(int A=0;A<2;++A)for(int B=0;B<2;++B)for(int i=0;i<3;++i)for(int j=0;j<3;++j){qt[lev][A][B]+=w[k]*e[A][i]*e[B][j]*h1[i][j];qtt[lev][A][B]+=w[k]*e[A][i]*e[B][j]*h2[i][j];}}
 double x=n[0],y=n[1],z=n[2],T[3]{},dt[3][3]{};if(which==0){T[0]=-z*z*x;T[1]=-z*z*y;T[2]=z*(x*x+y*y);dt[0][0]=-z*z;dt[1][1]=-z*z;dt[2][0]=-2*z*x;dt[2][1]=-2*z*y;dt[0][2]=2*z*x;dt[1][2]=2*z*y;dt[2][2]=x*x+y*y;}else{T[0]=-y;T[1]=x;dt[1][0]=-1;dt[0][1]=1;}
